function Glyph({ name, weight = "regular", size = 22, color = "currentColor", title, ...rest }: GlyphProps & { name: string }) {
  const outline = PATHS[name][weight];
  const a11y = title ? { role: "img" } : { "aria-hidden": true };
  return (
    <svg viewBox="0 0 256 256" width={size} height={size} fill={color} focusable="false" {...a11y} {...rest}>
      {title ? <title>{title}</title> : null}
      {outline.secondary ? <path d={outline.secondary} opacity={0.2} /> : null}
      <path d={outline.d} />
    </svg>
  );
}

export function MmMark(props: GlyphProps) {
  return <Glyph name="mm-mark" {...props} />;
}

export function StripScroll(props: GlyphProps) {
  return <Glyph name="strip-scroll" {...props} />;
}

export function PanelFocus(props: GlyphProps) {
  return <Glyph name="panel-focus" {...props} />;
}

export function BubbleSearch(props: GlyphProps) {
  return <Glyph name="bubble-search" {...props} />;
}

export function AgeGate(props: GlyphProps) {
  return <Glyph name="age-gate" {...props} />;
}

export function Voice31(props: GlyphProps) {
  return <Glyph name="voice-31" {...props} />;
}

export function Droplet(props: GlyphProps) {
  return <Glyph name="droplet" {...props} />;
}

export function Flywheel(props: GlyphProps) {
  return <Glyph name="flywheel" {...props} />;
}

/** strata-1 … strata-4: the number of lit bars, counted from the bottom. */
export function Strata({ level, ...props }: GlyphProps & { level: 1 | 2 | 3 | 4 }) {
  return <Glyph name={`strata-${level}`} {...props} />;
}

export function SparkleSlash(props: GlyphProps) {
  return <Glyph name="sparkle-slash" {...props} />;
}

export const GLYPHS = {
  "mm-mark": MmMark,
  "strip-scroll": StripScroll,
  "panel-focus": PanelFocus,
  "bubble-search": BubbleSearch,
  "age-gate": AgeGate,
  "voice-31": Voice31,
  "droplet": Droplet,
  "flywheel": Flywheel,
  "strata": Strata,
  "sparkle-slash": SparkleSlash,
} as const;

export type GlyphName = keyof typeof GLYPHS;
